x-509.pseudocode:
def validate_chain(chain, anchors, now):
    # chain[0]: 리프(서버) 인증서 → 상위 CA 순서
    for i, cert in enumerate(chain):
        if not (cert.not_before <= now <= cert.not_after):
            return False  # 유효기간 위반
        if is_revoked(cert):  # CRL·OCSP 조회
            return False
        if i + 1 < len(chain):
            issuer = chain[i + 1]
        else:
            issuer = anchors.get(cert.issuer)  # 신뢰 루트
            if issuer is None:
                return False  # 신뢰 앵커에 도달 못함
        if i > 0 and not cert.is_ca:
            return False  # 중간 인증서는 CA여야 함
        if cert.issuer != issuer.subject:
            return False  # 발급자-주체 이름 연결 확인
        if not verify_sig(issuer.public_key, cert):
            return False  # 상위 공개키로 tbs 서명 검증
    return True
